@OptIn(ExperimentalMaterial3Api::class)
@Composable fun PosApp(store:Store,printer:PrinterManager,heard:String,voiceStatus:String,scanStatus:String,clearHeard:()->Unit,listen:()->Unit,openSpeechSettings:()->Unit,exportMenu:()->Unit,importMenu:()->Unit,pickLogo:()->Unit,scanDocument:()->Unit,exportBackup:()->Unit,importBackup:()->Unit){
 var tab by remember{mutableIntStateOf(0)};var cart by remember{mutableStateOf(emptyList<SaleItem>())};var cash by remember{mutableStateOf(store.cash())};var tick by remember{mutableIntStateOf(0)};var filter by remember{mutableIntStateOf(0)};var editing by remember{mutableStateOf<PendingSale?>(null)};var settings by remember{mutableStateOf(false)};var expense by remember{mutableStateOf(false)};var opening by remember{mutableStateOf(!store.hasOpeningCash())};var selectedSale by remember{mutableStateOf<Sale?>(null)};var manualCart by remember{mutableStateOf(false)};var customerDialog by remember{mutableStateOf(false)};var customerName by remember{mutableStateOf("")};var customerPhone by remember{mutableStateOf("")}
 val menu=remember(tick){store.menu()};val profile=remember(tick){store.profile()};val sales=remember(tick){store.sales()};val expenses=remember(tick){store.expenses()};val pending=remember(tick){store.pending()}
 LaunchedEffect(heard){if(heard.isNotBlank()){VoiceCommandEngine.parse(heard,menu).forEach{command->when(command){is VoiceCommand.Add->{val i=cart.indexOfFirst{it.name.equals(command.item.name,true)&&it.price==command.item.price};cart=if(i>=0)cart.toMutableList().also{l->l[i]=l[i].copy(qty=l[i].qty+command.item.qty)}else cart+command.item};VoiceCommand.Clear->cart=emptyList();VoiceCommand.Sales->tab=3;VoiceCommand.Expenses->tab=4;VoiceCommand.Reports->tab=5;VoiceCommand.Settings->settings=true;VoiceCommand.Menu->tab=1;VoiceCommand.Kitchen->tab=2;VoiceCommand.Analytics->tab=5;VoiceCommand.NewOrder->cart=emptyList();is VoiceCommand.PayLast->pending.lastOrNull()?.let{pay(it)};is VoiceCommand.Quantity->cart=cart.map{if(it.name.contains(command.name,true))it.copy(qty=(it.qty+command.delta).coerceAtLeast(0))else it}.filter{it.qty>0};is VoiceCommand.Remove->cart=cart.filterNot{it.name.contains(command.name,true)};VoiceCommand.CompletePrint->{if(cart.isNotEmpty()){val order=PendingSale(System.currentTimeMillis(),cart,System.currentTimeMillis(),customerName.trim(),customerPhone.trim());store.addPending(order);printer.printKitchen(kitchenReceipt(order,profile,store.theme()));cart=emptyList();customerName="";customerPhone="";tick++}};VoiceCommand.Complete->Unit}};clearHeard()}}
 fun sendOrder(){if(cart.isNotEmpty())customerDialog=true};fun sendOrderWithCustomer(name:String,phone:String){customerName=name.trim();customerPhone=phone.trim();val order=PendingSale(System.currentTimeMillis(),cart,System.currentTimeMillis(),customerName,customerPhone);store.addPending(order);printer.printKitchen(kitchenReceipt(order,profile,store.theme()));cart=emptyList();customerName="";customerPhone="";tick++};fun pay(order:PendingSale){val sale=Sale(order.id,order.items,order.total,System.currentTimeMillis());store.addSale(sale);cash+=sale.total;store.setCash(cash);store.removePending(order.id);printer.printCustomer(customerReceipt(sale,profile,store.theme()));tick++}
 Scaffold(topBar={CenterAlignedTopAppBar(title={Column(horizontalAlignment=Alignment.CenterHorizontally){Text(profile.name.ifBlank{"VOICE POS"},fontWeight=FontWeight.Bold);Text("VOICE POS • PREMIUM",style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.secondary)}},actions={IconButton(onClick={settings=true}){Icon(Icons.Default.Settings,"Settings")}})},bottomBar={NavigationBar{listOf("Sale","Menu","Kitchen","Sales","Expenses","Analytics").forEachIndexed{i,n->NavigationBarItem(tab==i,{tab=i},icon={Icon(listOf(Icons.Default.PointOfSale,Icons.Default.MenuBook,Icons.Default.Restaurant,Icons.Default.ReceiptLong,Icons.Default.Payments,Icons.Default.Insights)[i],n)},label={Text(n)})}}},floatingActionButton={ExtendedFloatingActionButton(onClick=listen,icon={Icon(Icons.Default.Mic,"Power Voice")},text={Text("POWER VOICE")},shape=CircleShape)}){padding->Box(Modifier.fillMaxSize().padding(padding)){when(tab){0->QuickSale(cart,voiceStatus,::sendOrder,listen,openSpeechSettings,{cart=emptyList()},{manualCart=true}){item,delta->cart=cart.map{if(it==item)it.copy(qty=(it.qty+delta).coerceAtLeast(0))else it}.filter{it.qty>0}};1->MenuPage(menu,store,tick,{tick++},exportMenu,importMenu,scanDocument){item->val i=cart.indexOfFirst{it.name.equals(item.name,true)&&it.price==item.price};cart=if(i>=0)cart.toMutableList().also{l->l[i]=l[i].copy(qty=l[i].qty+1)}else cart+SaleItem(item.name,1,item.price);tab=0};2->KitchenQueue(pending,profile,printer,::pay){editing=it};3->SalesPage(sales.filter{inRange(it.time,filter)},filter,{filter=it},{selectedSale=it});4->ExpensesPage(expenses.filter{inRange(it.time,filter)},filter,{filter=it}){expense=true};5->Analytics(sales.filter{inRange(it.time,filter)},expenses.filter{inRange(it.time,filter)},cash,filter,{filter=it})}}}
 if(settings)SettingsPage(store,printer,pickLogo,exportBackup,importBackup){settings=false;tick++};if(opening)OpeningCash{store.setOpeningCash(it);cash=it;opening=false};if(expense)ExpenseDialog({a,b,c->store.addExpense(Expense(System.currentTimeMillis(),a,b,c,System.currentTimeMillis()));expense=false;tick++}){expense=false};if(selectedSale!=null)SaleDetailDialog(selectedSale!!,profile,printer,store.theme()){selectedSale=null};if(customerDialog)CustomerDetailsDialog({n,p->customerDialog=false;sendOrderWithCustomer(n,p)}){customerDialog=false};if(manualCart)ManualAddDialog(menu,{item->cart+=item;manualCart=false},{manualCart=false},{n,q,p->cart+=SaleItem(n,q,p);manualCart=false})}
}

@Composable private fun MenuPage(menu:List<MenuItem>,store:Store,tick:Int,refresh:()->Unit,exportMenu:()->Unit,importMenu:()->Unit,scanDocument:()->Unit,addToCart:(MenuItem)->Unit){var adding by remember{mutableStateOf(false)};Column(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(6.dp)){Button(onClick={adding=true},modifier=Modifier.weight(1f)){Icon(Icons.Default.Add,null);Text("Add")};OutlinedButton(onClick=scanDocument,modifier=Modifier.weight(1f)){Icon(Icons.Default.DocumentScanner,null);Text("AI Scan")}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(6.dp)){OutlinedButton(onClick=exportMenu,modifier=Modifier.weight(1f)){Text("CSV Export")};OutlinedButton(onClick=importMenu,modifier=Modifier.weight(1f)){Text("CSV Import")}};Text("AI Scan reads product names and prices from photos/PDF menus and adds detected products automatically.",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant);if(menu.isEmpty())EmptyState(Icons.Default.MenuBook,"No products","Add products or scan a menu image/PDF.");LazyColumn{items(menu){item->Card(Modifier.fillMaxWidth().clickable{addToCart(item)}){Row(Modifier.fillMaxWidth().padding(14.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(item.name,fontWeight=FontWeight.SemiBold);val d=listOf(item.variant,item.size).filter{it.isNotBlank()}.joinToString(" • ");if(d.isNotBlank())Text(d,style=MaterialTheme.typography.bodySmall);Text(money(item.price),style=MaterialTheme.typography.bodySmall)};IconButton(onClick={store.removeMenuItem(item.id);refresh()}){Icon(Icons.Default.Delete,"Delete")}}}}}};if(adding)AddMenuDialog({n,v,s,p->store.addMenuItem(MenuItem(System.currentTimeMillis(),n.trim(),p,v.trim(),s.trim()));adding=false;refresh()}){adding=false}}

@Composable private fun SettingsPage(store:Store,printer:PrinterManager,pickLogo:()->Unit,exportBackup:()->Unit,importBackup:()->Unit,close:()->Unit){var profile by remember{mutableStateOf(store.profile())};var theme by remember{mutableStateOf(store.theme())};var customer by remember{mutableStateOf(store.customerPrinterAddress())};var kitchen by remember{mutableStateOf(store.kitchenPrinterAddress())};AlertDialog(onDismissRequest=close,title={Text("Business & Print Settings")},text={Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(7.dp)){Text("Business Data Transfer",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);Text("Move menu, sales, pending orders, expenses, cash, company profile, receipt settings and logo to another phone.",style=MaterialTheme.typography.bodySmall);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick=exportBackup,modifier=Modifier.weight(1f)){Text("EXPORT BACKUP")};OutlinedButton(onClick=importBackup,modifier=Modifier.weight(1f)){Text("IMPORT BACKUP")}};Text("Company",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);OutlinedTextField(profile.name,{profile=profile.copy(name=it)},label={Text("Company Name")});OutlinedTextField(profile.address,{profile=profile.copy(address=it)},label={Text("Address")},minLines=3);OutlinedTextField(profile.phone,{profile=profile.copy(phone=it)},label={Text("Phone")});OutlinedTextField(profile.footer,{profile=profile.copy(footer=it)},label={Text("Footer message")});Text("Company Logo",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Text(if(profile.logoPath.isBlank())"No logo uploaded"else"Logo uploaded ✓",Modifier.weight(1f));OutlinedButton(onClick=pickLogo){Text("UPLOAD / CHANGE")}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Sale receipt logo");Switch(profile.saleLogoEnabled,{profile=profile.copy(saleLogoEnabled=it)})};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Kitchen receipt logo");Switch(profile.kitchenLogoEnabled,{profile=profile.copy(kitchenLogoEnabled=it)})};Text("Receipt style",fontWeight=FontWeight.Bold);Row(Modifier.horizontalScroll(rememberScrollState())){ReceiptTheme.values().forEach{t->FilterChip(theme==t,{theme=t},label={Text(if(t==ReceiptTheme.ADVANCED_PREMIUM)"Advanced Premium"else t.name)})}};Text("Bluetooth printers",style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(onClick={printer.discoverNow()},modifier=Modifier.weight(1f)){Icon(Icons.Default.BluetoothSearching,null);Spacer(Modifier.width(6.dp));Text(if(printer.discovering)"Discovering…"else"Find printers")};OutlinedButton(onClick={printer.refresh()}){Icon(Icons.Default.Refresh,null);Text("Refresh")}};printer.devices.forEach{device->Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Text(device.name?:device.address,Modifier.weight(1f),maxLines=1);TextButton(onClick={customer=device.address}){Text(if(customer==device.address)"Receipt ✓"else"Receipt")};TextButton(onClick={kitchen=device.address}){Text(if(kitchen==device.address)"Kitchen ✓"else"Kitchen")}}}},confirmButton={TextButton(onClick={store.saveProfile(profile);store.setTheme(theme);store.setCustomerPrinterAddress(customer);store.setKitchenPrinterAddress(kitchen);close()}){Text("SAVE")}},dismissButton={TextButton(onClick=close){Text("CLOSE")}})}
